/* B22: illustrations embedded in course cards; no remote image dependencies. */
(function(){
const art={"tecnologia":"data:image/svg+xml;base64,","salud":"data:image/svg+xml;base64,","idiomas":"data:image/svg+xml;base64,","negocios":"data:image/svg+xml;base64,","marketing":"data:image/svg+xml;base64,","construccion":"data:image/svg+xml;base64,","real-estate":"data:image/svg+xml;base64,","finanzas":"data:image/svg+xml;base64,","profesional":"data:image/svg+xml;base64,"};
const coursePhotos={"PA-101":"data:image/jpeg;base64,","RE-101":"data:image/jpeg;base64,","TE-101":"data:image/jpeg;base64,","MKT-201":"data:image/jpeg;base64,","FIN-201":"data:image/jpeg;base64,","ID-101":"data:image/jpeg;base64,","CO-101":"data:image/jpeg;base64,","PA-201":"data:image/jpeg;base64,","RE-102":"data:image/jpeg;base64,","PA-106":"data:image/jpeg;base64,","PA-105":"data:image/jpeg;base64,","HLT-201":"data:image/jpeg;base64,","PA-203":"data:image/jpeg;base64,","NE-101":"data:image/jpeg;base64,","AI-101":"data:image/jpeg;base64,","BUS-201":"data:image/jpeg;base64,","RE-201":"data:image/jpeg;base64,","MA-101":"data:image/jpeg;base64,","FI-101":"data:image/jpeg;base64,","PA-102":"data:image/jpeg;base64,"};
const safe=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function decorate(){
  if(typeof catalog==='undefined'||!Array.isArray(catalog))return;
  for(const c of catalog){
    const card=document.getElementById('course-'+c.code);
    if(!card||card.querySelector('.pa-b22-course-visual'))continue;
    const picture=document.createElement('div');picture.className='pa-b22-course-visual';
    const image=document.createElement('img');image.src=coursePhotos[c.code]||art[c.category]||art.profesional;image.onerror=function(){this.onerror=null;this.src=art[c.category]||art.profesional};image.alt='';image.loading='lazy';image.decoding='async';image.width=500;image.height=350;
    picture.append(image);card.insertBefore(picture,card.firstChild);
  }
}
let pending=false;function schedule(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;decorate()})}
document.addEventListener('DOMContentLoaded',()=>{const list=document.getElementById('courseList');if(!list)return;new MutationObserver(schedule).observe(list,{childList:true});schedule()});
})();
